public class ScopeExample {
    private String name = "Outer";

    public void execute() {
        Runnable r = new Runnable() {
            private String name = "Inner";
            public void run() {
                // 'this' refers to the anonymous Runnable!
                System.out.println(this.name);
            }
        };
        r.run();
    }
}

