public record OrderSummary(String orderId, BigDecimal total, List<String> items) {
    // Compact constructor omits parameter list
    public OrderSummary {
        Objects.requireNonNull(orderId, "orderId required");
        if (total == null || total.signum() < 0) {
            throw new IllegalArgumentException("Invalid total");
        }
        // Defensive copy runs before fields are assigned!
        items = List.copyOf(items);
    }
}

